// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint64 seed, uint8 offset) public {
        seed = uint64(bound(seed, 1, type(uint64).max - 100));
        offset = uint8(bound(offset, 1, 100));

        address sender = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.assume(sender != address(0) && sender != address(c));

        vm.deal(sender, 10 ether);

        vm.warp(seed);
        uint256 blockNum = seed + offset;
        vm.roll(blockNum);

        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");

        if (blockNum % 15 == 0) {
            assertEq(address(c).balance, 0, "balance should be 0 after payout");
        } else {
            assertEq(address(c).balance, 10 ether, "balance should be 10 ether when no payout");
        }
    }
}
